#pragma once
// nr2003_blocks.h - per-car contiguous value blocks recovered from tester.exe
//
// GENERATED by ghidra/gen_nr2003_blocks.py - do not hand-edit the tables.
//
// tester.exe (VB6 "Physics Tester") does NOT touch 2924 scattered &H addresses.
// Its live read/write loops walk per-car CONTIGUOUS float runs
// (tester/out/decomp_CALLER_0041ab40_FUN_0041ab40.c:64-139):
//
//   local_2c = blockBaseVA;
//   do { FUN_0042aa20(&local_2c, &buf); local_2c += 4; } while (uVar3 < 0x72);
//
// so one 114-float chassis block = 114 READ4 calls we collapse into a single
// ReadProcessMemory of 456 bytes.  Base arrays:
//   chassis - decomp_CALLER_0041ab40.c, param_1[0x2c]+0x08..0x5c  (22 entries)
//   engine  - decomp_CALLER_0041a000.c, unaff_EDI[0x33]+0x08..0x44 (16 entries)
//   wheel   - decomp_CALLER_0041ab40.c, piVar4[0x3a]+0x08..0x6c     (26 entries)
//   memloc  - the 23 "Mem Loc - Data Table" pointers the chassis blocks hold
//
// Section map of the supported 1.2.0.1-derived EXE (imagebase 0x400000):
//   .text  RVA 0x001000 len 0x2E8000  chars 0x60000020 READ|EXEC|CODE
//   .rdata RVA 0x2E9000 len 0x032000  chars 0x40000040 READ|DATA   (delta 0)
//   .data  RVA 0x31B000 len 0x895000  chars 0xC0000040 READ|WRITE|DATA
//   .rsrc  RVA 0xBB0000 len 0x042000
// Under Wine NtWriteVirtualMemory enforces page protection, so .rdata blocks
// (all 16 engine series) need the pre-race VirtualProtectEx path or the offline
// EXE patcher (tester/python/write_csv_to_exe.py).
//
// ------------------------------------------------------------------
// VERIFIED 2026-09-26 against a live NR2003 via BLOCKR (see the 87-block
// sweep in the session log).  Three facts fell out of that and are now baked
// in here:
//
// 1. BOTH tester accessors are the same READ4.  decomp_42AB00_FUN_0042ab00.c
//    is byte-identical to decomp_42AA20L_FUN_0042aa20.c except for the VB6
//    exception-list data block (DAT_00401600 vs DAT_004015f0).  There is NO
//    pointer indirection and no per-field accessor switch, so a block IS a
//    uniform flat run of floats.  The field indices tester skips when it
//    builds its CSV ({1,2,0x14,0x15,0x16,0x17,0x28,0x6F,0x72}) are a display
//    filter only - those slots exist in memory and a whole-block write must
//    include them.
//
// 2. block k <-> CSV COLUMN k, in FILE ORDER (not sorted!).  Chassis columns
//    are cup-5,cup-1,cup-2,cup-3,cup-4,cup-0,gns-5,gns-1,gns-2,gns-3,gns-4,
//    gns-0,cts-5&1,cts-2,cts-3,cts-4,cts-0,pta-5&1,pta-2,pta-3,pta-4,pta-0 -
//    so cup-0 is column 5, gns-0 column 11, cts-0 column 16, pta-0 column 21.
//    Getting this wrong (sorting the columns, or letting the 0x4945B8 outlier
//    consume a 0x1C8 stride slot) drops the match rate from 73% to 63% and
//    makes the last block match 2/114 instead of 87/114.
//
// 3. slot i <-> CSV row Field(i + fieldOffset), where fieldOffset is 1 for
//    chassis and wheel, 3 for engine (Field00=ID Num, Field01=Series (a string)
//    and Field02=Chassis are not in the block).  Live match rates: wheel
//    936/936 = 100%, chassis 1833/2508 = 73%, engine 28/28 on the tested
//    series.  The 27% chassis gap is fully accounted for:
//      - slots 59..81 (0x3B..0x51) are the 23 Mem Loc POINTERS, stored as
//        uint32 bits reinterpreted as float (23 "mismatches")
//      - slots 0,1,19,20,21,22,39 are 0-based integer index fields, so
//        memory = CSV - 1 because the CSV is 1-based (7 "mismatches")
//      - slot 110 (Field111) is NaN in memory vs -1 in the CSV (1 mismatch)
//    23 + 7 + 1 = 31, and 114 - 31 = 83 exact per block, which is what the
//    sweep measured.
//
// Slots 0x3B..0x51 of every chassis block hold ADDRESSES - the 23 "Mem Loc -
// Data Table" entries (VA 0x71F908..0x720928, all .data, stride 0xA0 = 40
// floats).  Tester only READS them as numbers but the game dereferences them,
// so per-car variants are edited by writing the pointed-to table, never the
// slot.  Overwriting a pointer slot with a float such as 0.0f (bit pattern
// 0x00000000) is what produced the NR2003 null-deref crash at 0x008be5e0.
//
// The static EXE file is NOT a valid oracle: the .data blocks are zero on disk
// and only populated at runtime (reading raw 0x323550 from the EXE gives
// zeros, 11/114 accidental "matches").  Only a live BLOCKR read is truthful.
//
// The per-value path (tester/python/fair_*.csv &H rows) is kept for stragglers,
// but note those &H values are RAW FILE OFFSETS of the static EXE, not RVAs -
// they only coincide with live addresses inside .rdata (which has delta 0).
// That is why fair_engine.csv lines up with the engine blocks (and fails with
// err 998) while fair_chassis/wheel/garage do not line up with anything live.

#include <cstdint>

#define NR2003_BLOCK_MAGIC  0x314B4C42u // "BLK1" LE
#define NR2003_BLOCK_MAX    96u

#define NR2003_BLOCK_MOD_CHASSIS 1u
#define NR2003_BLOCK_MOD_ENGINE  2u
#define NR2003_BLOCK_MOD_WHEEL   3u
#define NR2003_BLOCK_MOD_MEMLOC  4u

#define NR2003_BLOCK_FLAG_RDATA  0x1u // block lives in .rdata (not writable under Wine)
#define NR2003_BLOCK_FLAG_OUTLIER 0x2u // breaks the uniform stride; mapping verified

#pragma pack(push,1)

struct Nr2003BlockDesc {
    uint32_t baseRva;    // runtime VA = 0x400000 + baseRva
    uint16_t floatCount; // contiguous Sing floats
    uint8_t  module;     // NR2003_BLOCK_MOD_*
    uint8_t  flags;      // NR2003_BLOCK_FLAG_*
    char     name[22];   // tester series column name
    uint8_t  csvCol;     // column index in tester/mem_address/*-Mem.csv
    uint8_t  fieldOffset;// slot i <-> CSV row Field(i + fieldOffset)
};

struct Nr2003BlockTable {
    uint32_t magic;      // NR2003_BLOCK_MAGIC
    uint32_t count;      // valid entries in blocks[]
    Nr2003BlockDesc blocks[NR2003_BLOCK_MAX];
};

#pragma pack(pop)

