// slot -> FieldNN row index, per module.
static inline uint32_t nr2003_block_field_index(uint8_t module, uint32_t slot)
{
    switch (module) {
    case NR2003_BLOCK_MOD_ENGINE:  return slot + 3u; // Field00/01/02 are metadata
    case NR2003_BLOCK_MOD_MEMLOC:  return 0xFFFFFFFFu;
    default:                       return slot + 1u;
    }
}

// Human-readable field label for a slot, or "" when unknown.
static inline const char *nr2003_block_field_name(uint8_t module, uint32_t slot)
{
    switch (module) {
    case NR2003_BLOCK_MOD_CHASSIS:
        return slot < 114u ? NR2003_CHASSIS_FIELDS[slot] : "";
    case NR2003_BLOCK_MOD_ENGINE:
        return slot < 28u ? NR2003_ENGINE_FIELDS[slot] : "";
    case NR2003_BLOCK_MOD_WHEEL:
        return slot < 36u ? NR2003_WHEEL_FIELDS[slot] : "";
    default:
        return "";
    }
}

// .rdata RVA window of the supported EXE (see header comment)
#define NR2003_RDATA_RVA_LO 0x2E9000u
#define NR2003_RDATA_RVA_HI 0x312000u  // 0x2E9000 + 0x32000

static inline int nr2003_block_is_rdata(uint32_t rva)
{
    return rva >= NR2003_RDATA_RVA_LO && rva < NR2003_RDATA_RVA_HI;
}

// Slots 59..81 (0x3B..0x51) of every chassis block hold ADDRESSES the game
// dereferences.  Writing a float there is how NR2003 got a null pointer and
// crashed at 0x008be5e0.  Callers must keep these slots, so the block path
// refuses them outright.  NOTE: this is slot-based, not byte-based; the
// corresponding byte window is baseRva + 0x3B*4 .. baseRva + 0x52*4.
#define NR2003_BLOCK_PTR_SLOT_LO 0x3Bu
#define NR2003_BLOCK_PTR_SLOT_HI 0x51u
#define NR2003_BLOCK_PTR_COUNT   23u

static inline int nr2003_block_is_ptr_slot(uint32_t slot)
{
    return slot >= NR2003_BLOCK_PTR_SLOT_LO && slot <= NR2003_BLOCK_PTR_SLOT_HI;
}
